            <p className="text-muted-foreground mb-4">{t("footer.tagline")}</p>
            <p className="text-sm text-muted-foreground">{t("footer.copyright")}</p>
          </div>
        </footer>
      )}

      {/* Floating Chat Button */}
      {!isChat && <FloatingChatButton />}
    </div>
  );
}

client/src/hooks/use-mobile.tsx.content:
import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

client/src/hooks/use-toast.ts.content:
import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

client/src/hooks/useChat.ts.content:
import { useState, useEffect } from "react";
import { useProfile } from "./useProfile";
import { useWeather } from "./useWeather";
import { aiService } from "../services/aiService";
import { translationService } from "../services/translationService";
import { storageService } from "../services/storageService";
import type { ChatMessage } from "../types";

export function useChat() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const { profile } = useProfile();
  const { weather } = useWeather();

  // Load chat history on mount
  useEffect(() => {
    const loadChatHistory = async () => {
      if (profile?.id) {
        const history = await storageService.getChatHistory(profile.id);
        setMessages(history);
      }
    };
    loadChatHistory();
  }, [profile?.id]);

  // Add welcome message if no messages
  useEffect(() => {
    if (messages.length === 0 && profile) {
      const welcomeMessage: ChatMessage = {
        id: "welcome",
        sender: "bot",
        message: "🙏 Namaste! I'm KRISHI SAKHI, your AI farming companion. I can help you with crop advice, weather insights, and farming best practices. How can I assist you today?",
        timestamp: new Date(),
      };
      setMessages([welcomeMessage]);
    }
  }, [messages.length, profile]);

  const sendMessage = async (messageText: string) => {
    if (!profile || !messageText.trim()) return;

    setIsLoading(true);

    try {
      // Add user message
      const userMessage: ChatMessage = {
        id: Date.now().toString(),
        sender: "farmer",
        message: messageText,
        timestamp: new Date(),
        originalLanguage: profile.chatbotLanguage,
      };

      const updatedMessages = [...messages, userMessage];
      setMessages(updatedMessages);

      // Translate message to English if needed
      let englishMessage = messageText;
      if (profile.chatbotLanguage !== "en") {
        englishMessage = await translationService.translateText(
          messageText,
          profile.chatbotLanguage,
          "en"
        );
      }

      // Build context for AI
      const context = {
        profile: {
          name: profile.name,
          crop: profile.cropType,
          soil: profile.soilType,
          irrigation: profile.irrigation,
          landSize: `${profile.landSize} ${profile.landUnit}`,
          location: profile.location,
        },
        weather: weather ? {
          tempC: weather.tempC,
          humidity: weather.humidity,
          condition: weather.condition,
          rainProb: Math.round(weather.rainProb24h * 100),
        } : null,
        recentMessages: updatedMessages.slice(-6), // Last 3 exchanges
      };

      // Get AI response
      const aiResponse = await aiService.getChatResponse(englishMessage, context);

      // Translate response back to chatbot language if needed
      let translatedResponse = aiResponse;
      if (profile.chatbotLanguage !== "en") {
        translatedResponse = await translationService.translateText(
          aiResponse,
          "en",
          profile.chatbotLanguage
        );
      }

      // Add bot message
      const botMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        sender: "bot",
        message: translatedResponse,
        timestamp: new Date(),
      };

      const finalMessages = [...updatedMessages, botMessage];
      setMessages(finalMessages);

      // Save to storage
      await storageService.saveChatHistory(profile.id!, finalMessages);

    } catch (error) {
      console.error("Error sending message:", error);

      // Add error message
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        sender: "bot",
        message: "I'm sorry, I'm having trouble responding right now. Please try again later.",
        timestamp: new Date(),
      };

      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  return {
    messages,
    sendMessage,
    isLoading,
  };
}

