                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="soilType"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>
                            {t("profile.soilType")} *
                          </FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
