                              <Select onValueChange={unitField.onChange} defaultValue={unitField.value}>
                                <SelectTrigger className="w-32" data-testid="select-land-unit">
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                  {unitOptions.map((option) => (
