const OPENWEATHER_API_KEY = import.meta.env.VITE_OPENWEATHER_API_KEY || "ad2346767fce3e9feefd0c79a65ddcc9";
const BASE_URL = "https://api.openweathermap.org/data/2.5";

export interface WeatherResponse {
  main: {
    temp: number;
    humidity: number;
  };
  weather: Array<{
    main: string;
    description: string;
  }>;
  wind: {
    speed: number;
  };
  clouds: {
    all: number;
  };
  rain?: {
    "1h": number;
  };
}

export interface ForecastResponse {
  list: Array<{
    main: {
      temp: number;
      humidity: number;
    };
    weather: Array<{
      main: string;
      description: string;
    }>;
    pop: number; // Probability of precipitation
    dt_txt: string;
  }>;
}

class WeatherService {
  async getCurrentWeather(location: string) {
    try {
      // Get coordinates for location
      const geoResponse = await fetch(
        `https://api.openweathermap.org/geo/1.0/direct?q=${encodeURIComponent(location)}&limit=1&appid=${OPENWEATHER_API_KEY}`
      );

      if (!geoResponse.ok) {
        throw new Error("Failed to get location coordinates");
      }

      const geoData = await geoResponse.json();
      if (!geoData || geoData.length === 0) {
        throw new Error("Location not found");
      }

      const { lat, lon } = geoData[0];

      // Get current weather
      const weatherResponse = await fetch(
        `${BASE_URL}/weather?lat=${lat}&lon=${lon}&appid=${OPENWEATHER_API_KEY}&units=metric`
      );

      if (!weatherResponse.ok) {
        throw new Error("Failed to fetch weather data");
      }

      const weatherData: WeatherResponse = await weatherResponse.json();

      // Get forecast for rain probability
      const forecastResponse = await fetch(
        `${BASE_URL}/forecast?lat=${lat}&lon=${lon}&appid=${OPENWEATHER_API_KEY}&units=metric&cnt=8`
      );

      let rainProb24h = 0;
      if (forecastResponse.ok) {
        const forecastData: ForecastResponse = await forecastResponse.json();
        // Calculate average rain probability for next 24 hours
        rainProb24h = forecastData.list.reduce((acc, item) => acc + item.pop, 0) / forecastData.list.length;
      }

      return {
        tempC: Math.round(weatherData.main.temp),
        humidity: weatherData.main.humidity,
        condition: weatherData.weather[0].description,
        rainProb24h,
        wind: Math.round(weatherData.wind.speed * 3.6), // Convert m/s to km/h
        forecastArray: [], // Could be populated with detailed forecast if needed
      };
    } catch (error) {
      console.error("Weather service error:", error);

      // Return fallback data for demo purposes
      return {
        tempC: 32,
        humidity: 75,
        condition: "partly cloudy",
        rainProb24h: 0.3,
        wind: 12,
        forecastArray: [],
      };
    }
  }

  async getDetailedForecast(location: string, days: number = 5) {
    try {
      // Implementation for detailed forecast
      // This would return daily forecasts for the specified number of days
      return [];
    } catch (error) {
      console.error("Forecast service error:", error);
      return [];
    }
  }
}

export const weatherService = new WeatherService();

